{
  "pilot_name": "1D spherical Einstein-scalar collapse discriminator",
  "goal": "Smallest reproducible numerical pilot that can distinguish dispersion, black-hole formation, and a candidate naked singularity in spherical Einstein-scalar collapse.",
  "scope": {
    "spacetime": "spherically symmetric, asymptotically flat",
    "matter": "minimally coupled real massless scalar field",
    "gravity": "Einstein equations with spherical symmetry",
    "dimensions": "3+1 reduced to 1+1 (radius-time) plus angular triviality",
    "excluded": [
      "rotation",
      "charge",
      "nonzero scalar mass",
      "nonminimal coupling",
      "full 3D dynamics"
    ]
  },
  "coordinates": {
    "primary": {
      "name": "generalized Painleve-Gullstrand (PG) / Schwarzschild-like areal coordinates",
      "form": "ds^2 = -alpha(t,r)^2 dt^2 + (dr + beta(t,r) dt)^2 + r^2 dOmega^2",
      "reason": "horizon crossing regular, outgoing null rays easy to track, apparent horizon defined locally by g^{rr}=0",
      "domain": "r in [0, r_max], t in [0, t_final]",
      "boundary": "r=0 regularity; r=r_max outgoing Sommerfeld-like scalar boundary condition"
    },
    "alternative_check": {
      "name": "double-null coordinates",
      "form": "ds^2 = -2 f(u,v) du dv + r(u,v)^2 dOmega^2",
      "reason": "excellent for null infinity, black-hole horizon, and naked-singularity visibility tests",
      "use": "cross-check only if time permits"
    }
  },
  "equations": {
    "matter": {
      "scalar": "Box(phi) = 0",
      "stress_tensor": "T_ab = partial_a phi partial_b phi - 1/2 g_ab (partial phi)^2"
    },
    "gravity_reduced": {
      "hamiltonian_constraint": "radial constraint for mass function m(t,r)",
      "momentum_constraint": "radial constraint for beta or alpha",
      "evolution": "evolution of extrinsic curvature or metric functions",
      "mass_function": "m(t,r) = r/2 (1 - g^{rr}) in PG form",
      "apparent_horizon": "g^{rr}=0, equivalently 2m/r = 1"
    },
    "regularity": {
      "origin": "phi even in r near r=0; metric functions smooth; no coordinate singularity",
      "gauge": "choose alpha to avoid collapse of lapse; e.g. alpha = 1 or alpha from maximal slicing if stable"
    }
  },
  "initial_data": {
    "family": "time-symmetric or nearly time-symmetric scalar pulse",
    "profile": "phi(0,r) = A exp(-((r-r0)/w)^2), Pi(0,r) = 0 or small",
    "parameters": {
      "A": "scalar amplitude",
      "r0": "pulse center, e.g. 5.0",
      "w": "pulse width, e.g. 1.0",
      "r_max": "e.g. 100.0",
      "resolution": "N_r in {400, 800, 1600, 3200}"
    },
    "critical_search": "bisection in A around apparent critical amplitude A*",
    "expected_regimes": {
      "dispersion": "A < A*: scalar radiates away, no apparent horizon, m/r < 1/2 everywhere",
      "black_hole": "A > A*: apparent horizon forms, trapped region grows, scalar falls in",
      "critical_candidate": "A ~ A*: scale-invariant behavior, possible naked singularity or critical collapse"
    }
  },
  "numerical_method": {
    "spatial_discretization": "finite differences, 4th-order centered for smooth regions; 2nd-order near origin",
    "time_integration": "method of lines with 3rd-order Runge-Kutta or 4th-order Runge-Kutta",
    "grid": "uniform r grid, cell-centered or vertex-centered with ghost cells for regularity",
    "origin": "use regularity conditions or staggered grid to avoid division by r",
    "outer_boundary": "outgoing scalar radiation condition: d_t phi + d_r phi + phi/r = 0 approximately",
    "constraint_damping": "optional small damping or projection to reduce constraint drift",
    "horizon_finder": "solve g^{rr}=0 along r at each time; track outermost apparent horizon",
    "singularity_handling": "do not excise; stop evolution if curvature invariant exceeds threshold or grid stretching becomes extreme"
  },
  "observables": {
    "global": [
      "total mass M_ADM at initial time",
      "final black-hole mass M_BH from apparent horizon area",
      "radiated energy E_rad = integral of scalar flux at r_max",
      "energy conservation error |M_ADM - M_BH - E_rad| / M_ADM"
    ],
    "local": [
      "minimum value of g^{rr} or maximum of 2m/r",
      "apparent horizon radius r_AH(t) if exists",
      "scalar field maximum |phi|_max(t)",
      "curvature invariant K = R_abcd R^abcd or Kretschmann scalar at origin",
      "central density or energy density rho_c(t)"
    ],
    "critical": [
      "black-hole mass scaling M_BH ~ (A - A*)^gamma",
      "maximum curvature scaling K_max ~ (A - A*)^(-2 gamma)",
      "echo period or self-similarity in near-critical evolution"
    ],
    "visibility": [
      "outgoing null geodesics from near-origin region",
      "redshift of photons emitted near center",
      "whether a null ray can escape to r_max before curvature blows up",
      "apparent horizon formation time vs singularity formation time"
    ]
  },
  "discriminators": {
    "dispersion": {
      "criteria": [
        "no apparent horizon at any time",
        "max 2m/r < 1 - epsilon",
        "scalar field amplitude decays to zero",
        "radiated energy accounts for initial mass within tolerance"
      ]
    },
    "black_hole": {
      "criteria": [
        "apparent horizon forms at finite r_AH > 0",
        "r_AH grows or stabilizes",
        "scalar field trapped inside horizon",
        "outgoing null rays from inside cannot reach r_max"
      ]
    },
    "candidate_naked_singularity": {
      "criteria": [
        "curvature invariant grows without bound near r=0",
        "no apparent horizon forms before curvature exceeds threshold",
        "outgoing null rays from near-singular region can reach r_max",
        "redshift remains finite along escaping rays",
        "scaling behavior consistent with critical collapse"
      ],
      "caution": "numerical evidence only; must pass convergence and visibility tests"
    }
  },
  "convergence_tests": {
    "spatial": {
      "method": "Richardson extrapolation",
      "resolutions": [400, 800, 1600, 3200],
      "observables": [
        "phi at fixed r,t",
        "r_AH(t)",
        "K_max(t)",
        "M_BH",
        "E_rad"
      ],
      "target": "observed order p >= 1.8 for 2nd-order regions; report p for each observable",
      "criterion": "differences between successive resolutions decrease at expected rate"
    },
    "temporal": {
      "method": "fix spatial resolution, vary CFL by factor 2",
      "target": "stable convergence and no secular drift in constraints"
    },
    "constraint": {
      "method": "monitor Hamiltonian and momentum constraint residuals",
      "target": "residuals converge to zero with resolution; no growth faster than linear in time"
    },
    "conservation": {
      "method": "energy budget",
      "target": "|M_ADM - M_BH - E_rad| / M_ADM < 1e-3 for resolved black-hole cases"
    },
    "self_convergence": {
      "method": "compare fine solution restricted to coarse grid",
      "target": "same convergence order as Richardson"
    }
  },
  "visibility_test": {
    "purpose": "distinguish true naked singularity from numerical artifact or horizon-hidden singularity",
    "method": {
      "null_geodesics": "integrate outgoing null geodesics in the numerical metric",
      "equation": "for PG coordinates, dr/dt = alpha - beta for outgoing null rays",
      "initial_conditions": "launch rays from r = r_small near origin at times when K is large",
      "escape_criterion": "ray reaches r_max with finite affine parameter and finite redshift",
      "redshift": "compute g_tt ratio or frequency ratio between emitter and observer",
      "horizon_check": "verify no apparent horizon encloses the emission point"
    },
    "outcomes": {
      "dispersion": "rays escape easily, low curvature, no singularity",
      "black_hole": "rays from inside r_AH cannot escape; those from outside can",
      "naked_singularity_candidate": "rays from near high-curvature region escape to r_max before K exceeds cutoff",
      "numerical_artifact": "escape depends strongly on resolution or violates convergence"
    },
    "criteria": [
      "visibility result stable across resolutions",
      "redshift finite and convergent",
      "no apparent horizon between emitter and r_max",
      "curvature at emission exceeds threshold but ray still escapes"
    ]
  },
  "implementation_plan_1_week_cpu": {
    "day_1": {
      "tasks": [
        "set up 1D spherical PG or double-null code skeleton",
        "implement grid, boundary conditions, initial data",
        "implement scalar field evolution and mass function",
        "unit tests: flat space scalar wave propagation"
      ],
      "deliverable": "code runs stable scalar pulse in fixed flat background"
    },
    "day_2": {
      "tasks": [
        "couple gravity via constraints and evolution",
        "implement apparent horizon finder",
        "implement energy budget diagnostics",
        "test weak-field limit against linearized theory"
      ],
      "deliverable": "self-gravitating scalar evolution with constraints monitored"
    },
    "day_3": {
      "tasks": [
        "run parameter sweep in A to locate A*",
        "implement bisection for critical amplitude",
        "run low-resolution dispersion and black-hole cases",
        "verify expected qualitative behavior"
      ],
      "deliverable": "A* estimate and regime map"
    },
    "day_4": {
      "tasks": [
        "run convergence tests at 400, 800, 1600, 3200",
        "compute Richardson order for key observables",
        "check constraint and energy conservation",
        "identify numerical thresholds for curvature cutoff"
      ],
      "deliverable": "convergence report and validated resolution requirements"
    },
    "day_5": {
      "tasks": [
        "run near-critical cases at highest affordable resolution",
        "compute scaling of M_BH and K_max",
        "implement null geodesic visibility test",
        "run visibility test for dispersion, black-hole, and near-critical cases"
      ],
      "deliverable": "discrimination between dispersion, black hole, and naked-singularity candidate"
    },
    "day_6": {
      "tasks": [
        "cross-check with double-null coordinates if time permits",
        "repeat key runs with different gauge or boundary condition",
        "estimate systematic uncertainties",
        "produce final plots and tables"
      ],
      "deliverable": "robustness assessment and final observables"
    },
    "day_7": {
      "tasks": [
        "write reproducible report with JSON metadata",
        "archive code, parameters, and outputs",
        "document failure modes and next steps",
        "prepare minimal reproduction script"
      ],
      "deliverable": "complete reproducible pilot package"
    }
  },
  "computational_resources": {
    "hardware": "single CPU node, 8-16 cores, 32-64 GB RAM",
    "language": "Python with NumPy/SciPy or C/C++ for speed",
    "parallelization": "OpenMP or multiprocessing over parameter sweeps",
    "estimated_runtime": {
      "low_res_sweep": "hours",
      "high_res_critical": "1-2 days",
      "total": "within 1 week"
    },
    "storage": "few GB for outputs and checkpoints"
  },
  "success_criteria": {
    "minimum": [
      "stable evolution for dispersion and black-hole cases",
      "apparent horizon finder works",
      "convergence order >= 1.8 for key observables",
      "energy conservation error < 1e-3 for black-hole cases"
    ],
    "discrimination": [
      "dispersion: no horizon, scalar decays, energy radiated",
      "black hole: horizon forms, scalar trapped, energy budget closed",
      "naked singularity candidate: high curvature without horizon, escaping null rays, convergent visibility"
    ],
    "reproducibility": [
      "all parameters and seeds recorded",
      "one-command reproduction script",
      "JSON output with observables and convergence metrics"
    ]
  },
  "risks_and_mitigations": {
    "gauge_pathologies": "use regular PG coordinates or maximal slicing; monitor lapse",
    "constraint_drift": "use constraint damping or higher resolution",
    "horizon_finder_failure": "use multiple methods: g^{rr}=0 and 2m/r=1",
    "singularity_cutoff": "choose curvature threshold based on convergence; report sensitivity",
    "false_naked_singularity": "require visibility test and convergence; cross-check with double-null",
    "critical_scaling_noise": "use bisection and Richardson extrapolation; report error bars"
  },
  "output_json_schema": {
    "pilot": "string",
    "parameters": {
      "A": "float",
      "r0": "float",
      "w": "float",
      "r_max": "float",
      "N_r": "int",
      "t_final": "float",
      "CFL": "float"
    },
    "regime": "dispersion | black_hole | naked_singularity_candidate | inconclusive",
    "observables": {
      "M_ADM": "float",
      "M_BH": "float or null",
      "E_rad": "float",
      "energy_error": "float",
      "r_AH_final": "float or null",
      "max_2m_over_r": "float",
      "K_max": "float",
      "phi_max": "float"
    },
    "convergence": {
      "order_phi": "float",
      "order_r_AH": "float or null",
      "order_K_max": "float",
      "constraint_residual": "float"
    },
    "visibility": {
      "escaped": "bool",
      "redshift": "float or null",
      "horizon_encloses_emitter": "bool",
      "resolution_stable": "bool"
    },
    "notes": "string"
  }
}
